import { readFileSync } from "node:fs";
import type { Page } from "@playwright/test";
import { expect, test } from "./fixtures";

/** Reads the fictional demo credentials generated by `npm run db:seed-demo`. */
function demo() {
  const txt = readFileSync(".demo-credentials.txt", "utf8");
  const password = /Password for every demo account: (\S+)/.exec(txt)![1]!;
  const emp = /Employee:\s+(\S+)/.exec(txt)![1]!;
  const vendors = [...txt.matchAll(/Vendor:\s+(\S+)/g)].map((m) => m[1]!);
  return { password, admin: "ceo@demo.expenvia.test", emp, vendorA: vendors[0]!, vendorB: vendors[1]! };
}

async function signIn(page: Page, email: string, password: string) {
  await page.context().clearCookies();
  await page.goto("/login");
  await page.getByLabel(/Email address/i).fill(email);
  await page.getByLabel(/^Password/i).first().fill(password);
  await page.getByRole("button", { name: /^Sign in$/ }).click();
  await page.waitForURL(/\/(admin|user|vendor)\/dashboard/, { timeout: 30_000 });
}

test.beforeEach(async ({ context }) => {
  await context.addCookies([{ name: "NEXT_LOCALE", value: "en", url: "http://localhost:3002" }]);
});

test("landing page renders with brand and no framework branding", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(/Every Branch\. Every Expense\. One Clear View\./);
  await expect(page.locator("body")).not.toContainText(/Vercel|Next\.js|Create Next App/);
  expect(await page.locator('link[rel="icon"]').getAttribute("href")).toContain("icon.png");
});

test("switching to Urdu sets lang=ur and dir=rtl without a full reload", async ({ page }) => {
  await page.goto("/");
  await page.evaluate(() => ((window as unknown as { __marker: number }).__marker = 1));
  await page.getByRole("radio", { name: "اردو" }).first().click();
  await expect(page.locator("html")).toHaveAttribute("dir", "rtl");
  await expect(page.locator("html")).toHaveAttribute("lang", "ur");
  expect(await page.evaluate(() => (window as unknown as { __marker?: number }).__marker)).toBe(1);
});

test("protected routes redirect anonymous visitors to sign in", async ({ page }) => {
  for (const path of ["/admin/dashboard", "/user/expenses", "/vendor/invoices"]) {
    await page.goto(path);
    await expect(page).toHaveURL(/\/login$/);
  }
});

test("wrong password shows a generic error", async ({ page }) => {
  await page.goto("/login");
  await page.getByLabel(/Email address/i).fill("ceo@demo.expenvia.test");
  await page.getByLabel(/^Password/i).first().fill("definitely-wrong-1");
  await page.getByRole("button", { name: /^Sign in$/ }).click();
  await expect(page.getByText(/email or password is incorrect/i)).toBeVisible();
});

test("an employee cannot open admin pages or exports", async ({ page }) => {
  const d = demo();
  await signIn(page, d.emp, d.password);
  await page.goto("/admin/dashboard");
  await expect(page).toHaveURL(/\/unauthorized$/);
  const res = await page.request.get("/api/export/expenses");
  expect(res.status()).toBe(403);
});

test("a vendor cannot read another vendor's invoice, even by direct URL", async ({ page }) => {
  const d = demo();
  await signIn(page, d.vendorB, d.password);
  // Find one of vendor B's own invoice ids from their list, then sign in as vendor A and try it.
  await page.goto("/vendor/invoices");
  const href = await page.locator('main a[href^="/vendor/invoices/"]:not([href$="/new"])').first().getAttribute("href");
  test.skip(!href, "vendor B has no invoices in this seed");
  const id = href!.split("/").pop()!;
  await signIn(page, d.vendorA, d.password);
  // Streaming may send 200 before not-found resolves; what matters is that nothing leaks.
  await page.goto(`/vendor/invoices/${id}`);
  await expect(page.getByText(/Page not found/i)).toBeVisible();
  await expect(page.locator("main")).not.toContainText(/EXP-INV-/);
  const doc = await page.request.get(`/api/invoices/${id}/document?format=html`);
  expect(doc.status()).toBe(404);
});

test("admin can open the executive dashboard with charts", async ({ page }) => {
  const d = demo();
  await signIn(page, d.admin, d.password);
  await expect(page.getByRole("heading", { name: "Executive overview" })).toBeVisible();
  await expect(page.getByText("Monthly spending trend")).toBeVisible();
  await expect(page.locator(".recharts-surface").first()).toBeVisible();
});

test("@mobile dashboard has no horizontal page overflow", async ({ page }) => {
  const d = demo();
  await signIn(page, d.admin, d.password);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  expect(overflow).toBeLessThanOrEqual(1);
});

test("@mobile Urdu RTL pages fit the phone width for every role", async ({ page, context }) => {
  const d = demo();
  const check = async (paths: string[]) => {
    for (const p of paths) {
      await page.goto(p);
      await expect(page.locator("html")).toHaveAttribute("dir", "rtl");
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
      expect(overflow, `horizontal overflow on ${p}`).toBeLessThanOrEqual(1);
    }
  };
  await signIn(page, d.admin, d.password);
  await context.addCookies([{ name: "NEXT_LOCALE", value: "ur", url: "http://localhost:3002" }]);
  await check(["/admin/dashboard", "/admin/invoices", "/admin/approvals", "/admin/reports", "/admin/audit-logs", "/admin/settings"]);
  await signIn(page, d.emp, d.password);
  await context.addCookies([{ name: "NEXT_LOCALE", value: "ur", url: "http://localhost:3002" }]);
  await check(["/user/dashboard", "/user/expenses", "/user/expenses/new"]);
  await signIn(page, d.vendorA, d.password);
  await context.addCookies([{ name: "NEXT_LOCALE", value: "ur", url: "http://localhost:3002" }]);
  await check(["/vendor/dashboard", "/vendor/invoices", "/vendor/invoices/new", "/vendor/supplies"]);
});
